good.evals/oversight.py:
"""The oversight ledger: what a task cost on the people side.

The agent-side numbers (tokens, latency, tool calls) say nothing about whether a
pass was unattended, so this counts every unblock the run needed and the time
acceptance took, and refuses to let a row be reported without them.
"""
import dataclasses
import time


REQUIRED_FIELDS = ("intervention_count", "human_baseline_minutes", "human_review_seconds")


class UnscoreableRow(RuntimeError):
    """Raised instead of reporting an outcome with no oversight cost attached."""


@dataclasses.dataclass
class OversightLedger:
    task_id: str
    intervention_count: int = 0
    review_seconds: float = 0.0

    def record_intervention(self, reason: str) -> None:
        self.intervention_count += 1

    def record_review(self, seconds: float) -> None:
        self.review_seconds += seconds

    def assert_complete(self, row: dict) -> None:
        missing = [f for f in REQUIRED_FIELDS if row.get(f) is None]
        if missing:
            raise UnscoreableRow(
                f"task {self.task_id!r} reports an outcome with no oversight cost: {missing}"
            )

